 "contract_type": "nda",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Orchard Data Ltd."],
   "quote": "by and between Northwind Labs, Inc. (\"NORTHWIND\") and Orchard Data Ltd. (\"ORCHARD\")"
  },
  "counterparty": {
   "value": "Orchard Data Ltd.",
   "quote": "by and between Northwind Labs, Inc. (\"NORTHWIND\") and Orchard Data Ltd. (\"ORCHARD\")"
  },
  "effective_date": {
   "value": "2025-11-09",
   "quote": "entered into as of November 9, 2025 (the \"EFFECTIVE DATE\")"
  },
  "term_months": {"value": null, "quote": null},
  "auto_renewal": {"value": null, "quote": null},
  "renewal_notice_days": {"value": null, "quote": null},
  "governing_law": {
   "value": "Delaware",
   "quote": "the laws of the State of Delaware"
  },
  "liability_cap": {"value": null, "quote": null},
  "payment_terms_days": {"value": null, "quote": null},
  "contract_value": {"value": null, "quote": null},
  "termination_for_convenience": {"value": null, "quote": null},
  "confidentiality_years": {
   "value": 1,
   "quote": "The obligations in this Section 3 shall survive for one (1) years from the date of disclosure."
  }
 },
 "signers": [
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  },
  {
   "name": "Imogen Carter",
   "email": "imogen.carter@orchard.example",
   "title": "Managing Director",
   "party": "Orchard Data Ltd."
  }
 ],
 "risks": [
  {
   "id": "short_confidentiality_survival",
   "severity": "medium",
   "message": "Confidentiality obligations survive only one year from the date of each disclosure, so Northwind's confidential information (including any trade secrets) loses contractual protection quickly.",
   "quote": "The obligations in this Section 3 shall survive for one (1) years from the date of disclosure."
  },
  {
   "id": "no_term_or_termination_clause",
   "severity": "medium",
   "message": "The agreement has no stated term and no termination provision, yet the non-solicitation runs 'during the term' plus twelve months, leaving its duration ambiguous.",
   "quote": "During the term of this AGREEMENT and for twelve months thereafter, neither PARTY shall knowingly solicit for employment any PERSONNEL of the other PARTY"
  },
  {
   "id": "audit_rights_unusual_for_nda",
   "severity": "medium",
   "message": "Either party may audit the other's records, which is unusual in an NDA and gives Orchard access to Northwind's records and operations.",
   "quote": "Either PARTY may, upon reasonable prior notice and not more than once per year, audit the other PARTY's records, solely to verify compliance with this AGREEMENT."
  },
  {
   "id": "missing_confidential_information_definition",
   "severity": "high",
   "message": "CONFIDENTIAL INFORMATION is used throughout but never defined in the definitions section, and there are no standard exclusions (public information, independently developed, etc.), making the scope uncertain and hard to enforce.",
   "quote": "may disclose CONFIDENTIAL INFORMATION to one another."
  },
  {
   "id": "no_use_restriction",
   "severity": "medium",
   "message": "The agreement requires confidentiality but contains no explicit restriction limiting use of Confidential Information to the Purpose, and no remedies such as injunctive relief.",
   "quote": "shall hold the CONFIDENTIAL INFORMATION of the PARTY disclosing it (the \"DISCLOSING PARTY\") in strict confidence."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a mutual NDA between Northwind Labs, Inc. and Orchard Data Ltd., effective November 9, 2025 and governed by Delaware law, to evaluate a potential business relationship. Confidentiality obligations last only one year from each disclosure, and the agreement has gaps such as no definition of Confidential Information, no term, and an unusual audit right."
}
